  assert.deepEqual(await render({token:'room',bootstrapMode:mode}), {presence:{events:['room:bootstrap','room:update']},metrics:{events:['room:update']}});
}
const seen=[];
const a=createPresenceChannel('a');
const b=createPresenceChannel('b');
const nav=createWorkspaceNavigation((value,navigation)=>{seen.push(value);if(value==='a:bootstrap') navigation.select(b);});
nav.select(a);
a.emitUpdate();b.emitUpdate();
assert.deepEqual(seen,['a:bootstrap','b:bootstrap','b:update']);
nav.hide();b.emitUpdate();
assert.equal(seen.length,3);
let resolve;
const deferred=createPresenceChannel('old',{decode: value=>new Promise(done=>{resolve=()=>done(value);})});
const values=[];
const panel=createPresencePanel(value=>values.push(value));
panel.show(deferred);
panel.close();
panel.show(deferred);
resolve();
await Promise.resolve();
assert.deepEqual(values,['old:bootstrap']);
panel.close();
console.log('presence checks passed');
EOF"

